/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    Args            args;
    MenuFunction    menuFunction;

    InventSum   inventSum;
    InventDim   inventDim;

    select firstonly inventSum
        where inventSum.PhysicalInvent > 0
        join inventDim
            where inventDim.inventDimId     == inventSum.InventDimId
               && inventDim.wMSLocationId   == '151E010201';


    menuFunction    = new MenuFunction(menuitemActionStr(AVACreateCycleCountController), MenuItemType::Action);
    args            = new Args(menuFunction.object());

    args.caller(_args.caller());
    args.record(inventSum);
    menuFunction.run(args);
}
